from userclient.client import build_url


def test_build_url() -> None:
    assert build_url(7).endswith("/users/7")

"""Cache refresh."""

from .client import fetch

CACHE: dict[int, dict] = {}


def sync_all() -> None:
    """Refresh every cached user."""
    for user_id in list(CACHE):
        CACHE[user_id] = fetch(user_id)
